import{_ as l,r as a,o as r,c as p,e as t,a as e,s as c,d as n}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Mail Configuration - October CMS - 4.x","titleTemplate":false,"description":"Learn how to set up services for sending mail.","frontmatter":{"subtitle":"Learn how to set up services for sending mail."},"headers":[{"level":2,"title":"Driver Prerequisites","slug":"driver-prerequisites","link":"#driver-prerequisites","children":[{"level":3,"title":"Mailgun driver","slug":"mailgun-driver","link":"#mailgun-driver","children":[]},{"level":3,"title":"Postmark Driver","slug":"postmark-driver","link":"#postmark-driver","children":[]},{"level":3,"title":"SES driver","slug":"ses-driver","link":"#ses-driver","children":[]}]},{"level":2,"title":"Mail & Local Development","slug":"mail-local-development","link":"#mail-local-development","children":[{"level":3,"title":"Log Driver","slug":"log-driver","link":"#log-driver","children":[]},{"level":3,"title":"Universal To","slug":"universal-to","link":"#universal-to","children":[]},{"level":3,"title":"Pretend Mail Mode","slug":"pretend-mail-mode","link":"#pretend-mail-mode","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}]}],"relativePath":"4.x/setup/mail-config.md","filePath":"4.x/setup/mail-config.md"}'),d={name:"4.x/setup/mail-config.md"};function u(g,s,h,m,v,f){const o=a("pre-heading"),i=a("post-heading");return r(),p("div",null,[t(o),s[0]||(s[0]=e("h1",null,"Mail Configuration",-1)),t(i),s[1]||(s[1]=c(`<p>October CMS provides drivers for SMTP, Mailgun, SparkPost, Amazon SES and <code>sendmail</code>, allowing you to quickly get started sending mail through a local or cloud based service of your choice.</p><p>There are two ways to configure mail services, either using the admin panel via <strong>Settings → Mail Settings</strong> or by updating the default configuration values. In these examples we will update the file-based configuration values.</p><div class="custom-block tip"><p>​The mail settings screen in the admin panel will override the settings provided by the file-based configuration. Clicking the <strong>Reset to Default</strong> button will update the mail settings to the latest. If you do not click <strong>Save</strong> on this form, then the settings will continue to be sourced from the configuration files.</p></div><h2 id="driver-prerequisites"><a href="#driver-prerequisites" class="header-anchor">#</a> Driver Prerequisites</h2><p>In most cases you can use the SMTP driver and it will be supported by most mailing providers. However, using the API-based drivers are often a simpler and faster approach.</p><h3 id="mailgun-driver"><a href="#mailgun-driver" class="header-anchor">#</a> Mailgun driver</h3><p>To use the Mailgun driver, install Symfony&#39;s Mailgun Mailer transport via Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require symfony/mailgun-mailer symfony/http-client
</code></pre></div><p>Next, set the <code>driver</code> option in your <code>config/mail.php</code> configuration file to <code>mailgun</code>. Next, verify that your <code>config/services.php</code> configuration file contains the following options:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;mailgun&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;domain&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-domain&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-mailgun-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;endpoint&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;api.mailgun.net&#39;</span><span class="token punctuation">,</span> <span class="token comment">// api.eu.mailgun.net for EU</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="postmark-driver"><a href="#postmark-driver" class="header-anchor">#</a> Postmark Driver</h3><p>To use the Postmark driver, install Symfony&#39;s Postmark Mailer transport via Composer.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require symfony/postmark-mailer symfony/http-client
</code></pre></div><p>Next, set the <code>default</code> option in your application&#39;s <code>config/mail.php</code> configuration file to postmark. After configuring your application&#39;s default mailer, verify that your <code>config/services.php</code> configuration file contains the following.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;postmark&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;token&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">env</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;POSTMARK_TOKEN&#39;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="ses-driver"><a href="#ses-driver" class="header-anchor">#</a> SES driver</h3><p>To use the Amazon SES driver you must first install the Amazon AWS SDK for PHP. You may install this library via the Composer package manager.</p><div class="language-bash extra-class"><pre class="language-bash"><code><span class="token function">composer</span> require aws/aws-sdk-php
</code></pre></div><p>Next, set the <code>driver</code> option in your <code>config/mail.php</code> configuration file to <code>ses</code>. Then, verify that your <code>config/services.php</code> configuration file contains the following options:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;ses&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-key&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;secret&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;your-ses-secret&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;region&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;ses-region&#39;</span><span class="token punctuation">,</span>  <span class="token comment">// e.g. us-east-1</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h2 id="mail-local-development"><a href="#mail-local-development" class="header-anchor">#</a> Mail &amp; Local Development</h2><p>When developing an application that sends e-mail, you probably don&#39;t want to actually send e-mails to live e-mail addresses. There are several ways to &quot;disable&quot; the actual sending of e-mail messages.</p><h3 id="log-driver"><a href="#log-driver" class="header-anchor">#</a> Log Driver</h3><p>One solution is to use the <code>log</code> mail driver during local development. This driver will write all e-mail messages to your log files for inspection. For more information on configuring your application per environment, check out the <a href="./../setup/configuration.html">configuration documentation</a>.</p><h3 id="universal-to"><a href="#universal-to" class="header-anchor">#</a> Universal To</h3><p>Another solution is to set a universal recipient of all e-mails sent by the framework. This way, all the emails generated by your application will be sent to a specific address, instead of the address actually specified when sending the message. This can be done via the <code>to</code> option in your <code>config/mail.php</code> configuration file:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token string single-quoted-string">&#39;to&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;address&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;dev@example.tld&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Dev Example&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><h3 id="pretend-mail-mode"><a href="#pretend-mail-mode" class="header-anchor">#</a> Pretend Mail Mode</h3><p>You can dynamically disable sending mail using the <code>Mail::pretend</code> method. When the mailer is in pretend mode, messages will be written to your application&#39;s log files instead of being sent to the recipient.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">pretend</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4>`,31)),s[2]||(s[2]=e("div",{class:"custom-block also"},[e("ul",null,[e("li",null,[e("a",{href:"./../extend/system/sending-mail.html"},"Sending Mail")]),e("li",null,[e("a",{href:"https://github.com/rainlab/sparkpost-plugin",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[n("SparkPost Plugin"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),n(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),n(),e("span",{class:"sr-only"},"(opens new window)")])])])])],-1))])}const b=l(d,[["render",u]]);export{y as __pageData,b as default};
